from taf.sbts.oam.sc.rest.schemas.base import SchemaField, SchemaObject


class Paragraph(SchemaObject):
    type = SchemaField(name="type", not_null=True)
    title = SchemaField(name="title", optional=True)
    date_time = SchemaField(name="date_time", optional=True)
    text = SchemaField(name="text", optional=True)
    headers = SchemaField(name="headers", optional=True)
    rows = SchemaField(name="rows", optional=True)

    def __init__(self, type=None, title=None, date_time=None, text=None, headers=None, rows=None):
        self.type = type
        self.title = title
        self.date_time = date_time
        self.text = text
        self.headers = headers
        self.rows = rows
        super(Paragraph, self).__init__()


class TopologyUnitInfoParagraphTOPOLGYV1(Paragraph):
    paragraphs = SchemaField(name="paragraphs", klass=Paragraph, many=True, not_null=False)

    def __init__(self, paragraphs=None, type=None, title=None, date_time=None, text=None, headers=None, rows=None):
        self.paragraphs = paragraphs

        super(TopologyUnitInfoParagraphTOPOLGYV1, self).__init__(type=type, title=title, date_time=date_time, text=text,
                                                                 headers=headers, rows=rows)


class TopologyUnitInfoTOPOLGYV1(SchemaObject):
    name = SchemaField(name="name", not_null=True)
    paragraphs = SchemaField(name="paragraphs", klass=TopologyUnitInfoParagraphTOPOLGYV1, many=True, not_null=False)

    def __init__(self, name=None, paragraphs=None):
        self.name = name
        self.paragraphs = paragraphs
        super(TopologyUnitInfoTOPOLGYV1, self).__init__()
